bool
initGuardCStack(void)
{
#ifdef O_C_STACK_GUARDED
  GET_LD
  stack_t current;

  if ( sigaltstack(NULL, &current) != 0 )
    return false;
#ifdef O_PLMT
  if ( pthread_once(&signal_stack_once, create_signal_stack_key) != 0 ||
       !signal_stack_key_ready )
    return false;
#endif

  /* Reuse a registered stack when switching or creating another engine. */
  if ( current.ss_flags & SS_DISABLE )
  { void *memory;
#ifdef O_PLMT
    memory = pthread_getspecific(signal_stack_key);
#else
    memory = LD->signal.alt_stack;
#endif
    bool allocated = memory == NULL;
    if ( allocated && !(memory = malloc(SIGSTKSZ)) )
      return false;

    stack_t ss = {0};
    ss.ss_sp = memory;
    ss.ss_size = SIGSTKSZ;
    if ( sigaltstack(&ss, NULL) != 0 )
    { if ( allocated )
        free(memory);
      return false;
    }
#ifdef O_PLMT
    if ( allocated && pthread_setspecific(signal_stack_key, memory) != 0 )
    { (void)release_signal_stack(memory);
      return false;
    }
#else
    LD->signal.alt_stack = memory;
#endif
  }

  if ( LD == &PL_local_data )
  { struct sigaction sa = {0};
    sa.sa_flags = SA_ONSTACK;
    sa.sa_handler = alt_segv_handler;
    sigemptyset(&sa.sa_mask);
    return sigaction(SIGSEGV, &sa, NULL) == 0;
  }
  return true;
#else
  return false;
#endif
}
